examples.template:
Column(
    modifier = Modifier.widthIn(max = 640.dp),
    verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2),
) {
    MonarchAiContextChips(
        items = items,
        emptyText = {{empty}},
        onRemove = { id -> items = items.filterNot { it.id == id } },
        kindIcon = { kind ->
            MonarchIcon(
                when (kind) {
                    MonarchAiContextKind.File -> SampleIcons.Document
                    MonarchAiContextKind.Selection -> SampleIcons.BulletList
                    MonarchAiContextKind.Page -> SampleIcons.Window
                    MonarchAiContextKind.Record -> SampleIcons.Database
                    MonarchAiContextKind.App -> SampleIcons.Grid
                    MonarchAiContextKind.Person -> SampleIcons.Person
                },
                contentDescription = null,
                size = MonarchIconSize.Sm,
            )
        },
        removeIcon = { MonarchIcon(imageVector = SampleIcons.Close, contentDescription = null, size = MonarchIconSize.Sm) },
    )
    if (items.size < initial.size) {
        MonarchButton(
            text = {{reset}},
            onClick = { items = initial },
            variant = MonarchButtonVariant.Ghost,
            size = MonarchButtonSize.Sm,
        )
    }
}

